insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('comfort-someone-grief-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Comfort Someone Grief', 'A practical challenge that builds empathy and perspective-taking.', null, 'Ongoing', 'None', 'When someone you know is grieving: sit with them, listen, don''t fix. The skill of simply being present.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('build-radio-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Build Radio', 'A skill-building activity focused on sensory discrimination and integration.', 25, '20–30 min', 'Crystal radio kit (basic components)', 'Crystal radio receiver: wire antenna, capacitor, crystal diode, earphone. Receives AM radio without power. Electromagnetic field science.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('make-indigo-dye-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Make Indigo Dye', 'A skill-building activity focused on sensory discrimination and integration.', 38, '30–45 min', 'Indigo leaves or powder, water, reducing agent', 'Process indigo leaves (or buy powder) to create a vat. Dye cloth. Reduction chemistry + ancient textile tradition.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('soil-science-investigation-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Soil Science Investigation', 'A skill-building activity focused on tactile discrimination and refinement.', 18, '15–20 min', 'Soil samples, pH strip, water', 'Test soil pH, texture, and drainage in 3 different spots. What do the results mean for growing food?', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('kite-from-scratch-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Kite from Scratch', 'A skill-building activity focused on sensory discrimination and integration.', 25, '20–30 min', 'Bamboo, tissue paper, string, tape', 'Bamboo + tissue paper + string + tail. Design it, test it, adjust it. Aerodynamics through iteration.', 'This supports regulation and focus, which matters more once formal learning begins. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('night-photography-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Night Photography', 'An activity that develops sensory discrimination and integration.', 18, '15–20 min', 'Phone with night mode', 'Use a phone on night mode: photograph the moon, city lights, star trails (long exposure). Visual + astronomy.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Expect them to want to do it their own way, and let them where you can.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('basic-first-aid-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Basic First Aid', 'An activity that develops personal safety and judgement.', null, 'Ongoing', 'First aid course', 'Complete a basic first aid course (1-day). CPR, choking, burns, bleeding. Actual lifesaving capability.', 'Independence and responsibility at this age build competence that carries well beyond the specific task. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('manage-week-independently-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Manage Week Independently', 'A skill-building activity focused on household responsibility.', null, 'Ongoing', 'None', 'For one week, manage own morning routine, school bag, homework, and one household chore without reminders.', 'Children who genuinely contribute at home tend to be more capable and more confident. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('coach-younger-team-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Coach Younger Team', 'A practical challenge that builds running speed and endurance.', 38, '30–45 min', 'Sport equipment + younger players', 'Organise and run a sports activity for 5–8 younger children. Leadership + pedagogy + patience combined.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('marathon-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Marathon', 'A skill-building activity focused on running speed and endurance.', 38, '30–45 min', 'Open space or road (supervised)', 'Run a 5-km ''marathon'' with pacing and recovery strategy. Goal-setting + physical training + completion.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('bicycle-maintenance-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Bicycle Maintenance', 'A skill-building activity focused on cycling skill and road awareness.', 25, '20–30 min', 'Bicycle, tyre levers, pump, oil, cloth', 'Fix a puncture, oil the chain, adjust the brakes. Understanding and maintaining one''s own tools.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('full-season-participation-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Full Season Participation', 'A practical challenge that builds coordination, strength and control.', null, 'Ongoing', 'Sport-specific equipment', 'Commit to a sport for a full season. Regular training + team membership + end-of-season performance or competition.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swimming-medley-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Swimming Medley', 'An activity that develops swimming technique.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, swim an individual medley: butterfly, backstroke, breaststroke, freestyle in sequence. The most technically demanding swimming achievement.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('mountain-bike-trail-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Mountain Bike Trail', 'A skill-building activity focused on rhythm, sequence and coordination.', 25, '20–30 min', 'Mountain bike + trail', 'Trail mountain biking: technical terrain, root avoidance, off-camber sections. Mastery of cycling on a new surface.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('dance-choreograph-audience-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Dance Choreograph Audience', 'A practical challenge that builds rhythm, sequence and coordination.', 25, '20–30 min', 'Music + performance space', 'Choreograph a 2-minute dance piece and perform it for a real audience. Creative intention + public performance.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('free-solo-climbing-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Free Solo Climbing', 'A skill-building activity focused on climbing and whole-body strength.', 25, '20–30 min', 'Bouldering wall', 'Unsupported bouldering at an indoor wall: read the route, solve it. Self-directed physical problem-solving.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('write-novella-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Write Novella', 'An activity that develops handwriting control.', 45, '30–60 min', 'Pencil and paper (or computer)', 'Begin a sustained long-form writing project. Plot outline, chapter plan, daily writing practice. Authorial identity.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('working-model-engine-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Working Model Engine', 'A practical challenge that builds construction and spatial precision.', 38, '30–45 min', 'Kit or household materials (supervised)', 'Simple steam engine or electric motor model. How does energy convert into motion? Engineering science.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('ceramics-glazing-firing-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Ceramics Glazing Firing', 'A practical challenge that builds spatial reasoning through the hands.', 38, '30–45 min', 'Bisque-fired piece, glazes, kiln (art school)', 'Apply underglaze and overglaze to bisque-fired piece. Two-stage firing = colour chemistry through heat.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('wiring-simple-plug-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Wiring Simple Plug', 'An activity that develops fine motor precision and control.', 18, '15–20 min', 'Old plug, wire, screwdriver (supervised)', 'Supervised: identify live, neutral, earth in a plug; connect correctly. Electrical safety + practical knowledge.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('photography-composition-rules-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Photography Composition Rules', 'A practical challenge that builds fine motor precision and control.', 18, '15–20 min', 'Camera or phone', 'Rule of thirds, leading lines, framing. Apply all 3 in 5 intentional photos. Visual composition as deliberate craft.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Expect them to want to do it their own way, and let them where you can.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('weave-rug-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Weave Rug', 'A practical challenge that builds needle skills and precision.', 45, '30–60 min', 'Frame loom, yarn', 'A small rug on a frame loom: warp and weft at density. Sustained repetitive fine motor over a physical project.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('read-literature-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Read Literature', 'A practical challenge that builds reading development.', 25, '20–30 min', 'Classic novel in original text', 'Read an original, unabridged classic in full. Grapple with archaic language as a skill, not a barrier.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('formal-argument-essay-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Formal Argument Essay', 'A practical challenge that builds vocabulary depth.', 25, '20–30 min', 'Pencil and paper', '800 words: thesis, 3 body paragraphs with evidence and counter-argument addressed, conclusion. University-essay structure.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('public-speaking-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Public Speaking', 'A practical challenge that builds conversation and presentation.', 15, '10–20 min', 'Prepared speech', 'Present to an audience beyond family: school group, community, or recorded. Real audience = real feedback.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-research-paper-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Write Research Paper', 'A practical challenge that builds written expression.', 25, '20–30 min', 'Reference materials + pencil and paper', 'Includes a bibliography, quotes with attribution, and a distinct argument. Academic writing conventions.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('translate-short-text-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Translate Short Text', 'An activity that develops language, literacy and expression.', 13, '10–15 min', 'Short text + dictionary', 'Translate a simple paragraph to/from a second language. Bilingual flexibility and linguistic comparison.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('study-present-person-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Study Present Person', 'An activity that develops conversation and presentation.', 18, '15–20 min', 'Reference materials', 'In-depth research on one person: 10 facts, a timeline, one thing they changed. Oral presentation.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-letter-authority-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Write Letter Authority', 'An activity that develops written expression.', 18, '15–20 min', 'Pencil and paper or email access', 'Write a real letter (or email) to a local councillor, newspaper, or organisation about a real issue.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('discuss-dystopian-novel-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Discuss Dystopian Novel', 'A skill-building activity focused on conversation and presentation.', 18, '15–20 min', 'Age-appropriate dystopian novel', 'A gentle dystopian novel: what is the society afraid of? What does this tell us about our own world?', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('algebra-linear-equations-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Algebra Linear Equations', 'A practical challenge that builds planning and problem-solving.', 8, '5–10 min', 'Pencil and paper', 'Solve 2x + 3 = 11. Two-step equations with one variable. Algebraic reasoning + inverse operations.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('mean-median-mode-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Mean, Median, Mode', 'A practical challenge that builds reasoning, planning and problem-solving.', 8, '5–10 min', 'Data set + pencil and paper', 'Calculate all three for a data set. When would each be misleading? Statistical literacy begins here.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('understand-compound-interest-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Understand Compound Interest', 'A skill-building activity focused on reasoning, planning and problem-solving.', 8, '5–10 min', 'Pencil and paper', 'Interest on interest. Compare simple vs compound over 10 years. The most powerful concept in personal finance.', 'Understanding at this stage grows from working things out rather than being told the answer. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('ethics-trolley-problem-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Ethics Trolley Problem', 'A practical challenge that builds planning and problem-solving.', 13, '10–15 min', 'None', 'The trolley problem and its variants. There is no right answer: the process of reasoning is the point.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('evolution-natural-selection-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Evolution Natural Selection', 'A practical challenge that builds scientific reasoning.', 8, '5–10 min', 'None', 'Survival of the fittest: variation, selection pressure, inherited advantage, generation change. Darwin''s mechanism.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('study-civilisation-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Study Civilisation', 'An activity that develops reasoning, planning and problem-solving.', 18, '15–20 min', 'Reference book or supervised internet', 'Choose one ancient civilisation: research government, economy, culture, fall. Historical systems thinking.', 'Understanding at this stage grows from working things out rather than being told the answer. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('build-personal-vision-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Build Personal Vision', 'A practical challenge that builds empathy and perspective-taking.', 13, '10–15 min', 'None', 'What kind of person do I want to be at 18? At 30? What do I need to do to become that person?'' Long-range identity work.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('own-learning-style-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Own Learning Style', 'An activity that develops social understanding and self-regulation.', 8, '5–10 min', 'None', 'How do you learn best? What conditions make you most creative? What drains you? Self-awareness as meta-cognition.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('team-through-difficulty-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Team Through Difficulty', 'A practical challenge that builds friendship and social navigation.', null, 'Ongoing', 'None', 'When a group project hits a problem: step up, identify the issue, suggest a path forward. Leadership in adversity.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('mental-health-continuum-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Mental Health Continuum', 'A practical challenge that builds social understanding and self-regulation.', 8, '5–10 min', 'None', 'Mental health is not binary: everyone is somewhere on a continuum. What affects yours? How do you maintain it?', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('give-something-back-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Give Something Back', 'A skill-building activity focused on social understanding and self-regulation.', null, 'Ongoing', 'None', 'Identify a skill or resource you have and give it to someone who needs it. Generosity as identity, not event.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('who-am-i-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Who Am I', 'A practical challenge that builds social understanding and self-regulation.', 18, '15–20 min', 'Paper and pencil (optional)', 'Write or tell: your values, your strengths, your challenges, your culture, your aspirations. A portrait in words.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('rocketry-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Rocketry', 'An activity that develops sensory discrimination and integration.', 18, '15–20 min', 'Paper, tape, baking soda, vinegar, cork', 'Build a paper rocket body; launch with baking soda + vinegar. Newton''s 3rd law + trajectory + design iteration.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('bread-fermentation-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Bread Fermentation', 'A practical challenge that builds sensory art and material handling.', null, 'Ongoing', 'Flour, water, jar', 'Cultivate a sourdough starter over 5 days. Microbiology: wild yeast + bacteria + time = leavening.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('night-hike-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Night Hike', 'An activity that develops auditory discrimination.', 38, '30–45 min', 'Torch, safe trail, adult accompaniment', 'Hike 2 km at night using torchlight or moonlight. Sensory recalibration: vision changes, sound sharpens, fear and awe.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('build-drone-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Build Drone', 'An activity that develops auditory discrimination.', 38, '30–45 min', 'Simple drone kit', 'Assemble a simple drone kit. Lift, thrust, pitch, yaw, roll: four rotor forces that enable stable flight.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-graphic-novel-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Make Graphic Novel', 'An activity that develops sensory discrimination and integration.', 38, '30–45 min', 'Paper, pencil, markers', '10 pages: panels, speech bubbles, visual storytelling without verbal narration where possible. Comics as a serious medium.', 'This supports regulation and focus, which matters more once formal learning begins. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('responsible-technology-use-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Responsible Technology Use', 'A practical challenge that builds household responsibility.', 8, '5–10 min', 'Honest self-assessment', 'Review own technology use across a week: time, content, quality of experience. Intentional use vs reactive use.', 'Independence and responsibility at this age build competence that carries well beyond the specific task. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('button-hem-trousers-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Button, Hem Trousers', 'An activity that develops full dressing independence.', 13, '10–15 min', 'Needle, thread, garment', 'Practical clothing repair. These skills prevent waste and build material self-sufficiency.', 'This develops the organisation and self-management that school increasingly demands. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP')
